def generator(rng):
    # We want p_c > p_e, so d > 2.
    d = rng.choice([3, 4, 5, 6, 7, 8])

    # L=2 provides enough complexity without being overly tedious.
    L = 2
    alphabet = ['a', 'b']

    while True:
        u = "".join(rng.choice(alphabet) for _ in range(L))
        v = "".join(rng.choice(alphabet) for _ in range(L))

        # Avoid trivial case u=v, where P=1/2.
        if u != v:
            # Also avoid the original problem's setup where all positions are of the same type
            # This happens if u='aa', v='bb' or u='ab', v='ba' etc.
            # Let's check the position types
            pos_types = []
            for i in range(L):
                pair = tuple(sorted((u[i], v[i])))
                if u[i] == v[i]:
                    pos_types.append('same')
                elif pair == ('a', 'b'):
                    pos_types.append('diff')
            if len(set(pos_types)) > 1:
